import l from"./BaseSegment.js";import{Vec3 as p}from"../../math/Vec3.js";import{T_VALUES as c,C_VALUES as x}from"./utils.js";const a=new p;function r(s,i,t,n,h){const e=1-s;return e*e*e*i+3*e*e*s*t+3*e*s*s*n+s*s*s*h}function z(s,i,t,n,h){const e=1-s;return 3*e*e*(t-i)+6*e*s*(n-t)+3*s*s*(h-n)}class m extends l{constructor(i,t,n,h,e=0,o=0){super(),this.p0=i,this.p1=t,this.p2=n,this.p3=h,this.tiltStart=e,this.tiltEnd=o,this._len=-1}updateLength(){const t=c.length;let n=0;for(let h=0,e;h<t;h++)e=.5*c[h]+.5,n+=x[h]*this.getDerivativeAt(e,a).len();this._len=.5*n}getPointAt(i,t=new p){return t.x=r(i,this.p0.x,this.p1.x,this.p2.x,this.p3.x),t.y=r(i,this.p0.y,this.p1.y,this.p2.y,this.p3.y),t.z=r(i,this.p0.z,this.p1.z,this.p2.z,this.p3.z),t}getDerivativeAt(i,t=new p){return t.x=z(i,this.p0.x,this.p1.x,this.p2.x,this.p3.x),t.y=z(i,this.p0.y,this.p1.y,this.p2.y,this.p3.y),t.z=z(i,this.p0.z,this.p1.z,this.p2.z,this.p3.z),t}getTangentAt(i,t=new p){return this.getDerivativeAt(i,t).normalize()}lastPoint(){return this.p3}}export{m as default};
